static const char*complete(const char*path,const char*method,JsonObject out){JsonDocument e;e["operation_id"]=++operations;e["method"]=method;e["ok"]=true;out["operation_id"]=operations;core.emit(path,"operation_completed",e.as<JsonObjectConst>());return nullptr;}
static const char*camera(const char*m,JsonObjectConst a,JsonObject o){if(!strcmp(m,"read")){o["ready"]=camReady;o["operation_pending"]=false;o["frame_id"]=camFrame;if(camFrame){o["bytes"]=cameraBytes.size();o["width"]=320;o["height"]=240;}return nullptr;}if(!strcmp(m,"configure"))return nullptr;if(!strcmp(m,"stop")){camReady=false;camFrame=0;return complete("/dev/camera",m,o);}if(!strcmp(m,"start")){camReady=true;return complete("/dev/camera",m,o);}if(!strcmp(m,"capture")){camFrame=nextCameraFrame++;cameraAt=nowMs;return complete("/dev/camera",m,o);}if(!strcmp(m,"release")){camFrame=0;return nullptr;}if(!strcmp(m,"copy_frame")){const char*relative;auto p=vfs.resolve(a["file"],relative);assert(p&&!p->persistent);uint64_t at=0;assert(parseOffset(a["offset"],at));size_t wrote;std::vector<uint8_t>pixels(cameraBytes);if(a["pixel_format"]=="rgb565le")for(size_t i=0;i<pixels.size();i+=2)std::swap(pixels[i],pixels[i+1]);auto e=p->write(relative,at,pixels.data(),pixels.size(),false,wrote);if(e)return e;o["written"]=wrote;return nullptr;}if(!strcmp(m,"read_chunk")){size_t at=std::stoull(a["offset"].as<const char*>()),n=std::min<size_t>(a["length"]|1024u,cameraBytes.size()-at);char bytes[2049];if(a["pixel_format"]=="rgb565le"){uint8_t converted[1024];for(size_t i=0;i<n;++i)converted[i]=cameraBytes[at+(i^1u)];hex(converted,n,bytes);}else hex(cameraBytes.data()+at,n,bytes);o["hex"]=bytes;sizeText(o,"next_offset",at+n);return nullptr;}return "unsupported_method";}
static void step(unsigned count=1){static uint32_t cursor=0;while(count--){nowMs+=20;core.clock(nowMs);core.tick();core.dispatch(cursor);host->tick(nowMs);apps->poll();files->poll();}}
