static void checkButtons(){std::vector<lv_area_t>buttons;for(auto n=uiNodeRefs;n;n=n->next)if(lv_obj_check_type(n->node,&lv_button_class)){lv_area_t box;lv_obj_get_coords(n->node,&box);assert(box.x1>=0&&box.y1>=0&&box.x2<320&&box.y2<240);assert(box.x2-box.x1+1>=44&&box.y2-box.y1+1>=44);for(auto other:buttons)assert(box.x2<other.x1||box.x1>other.x2||box.y2<other.y1||box.y1>other.y2);buttons.push_back(box);for(unsigned i=0;i<lv_obj_get_child_count(n->node);++i){auto child=lv_obj_get_child(n->node,i);if(lv_obj_check_type(child,&lv_image_class)||lv_obj_check_type(child,&lv_label_class)){lv_area_t b;lv_obj_get_coords(child,&b);if(lv_obj_get_style_align(child,0)!=LV_ALIGN_DEFAULT||lv_obj_get_style_layout(n->node,0)==LV_LAYOUT_FLEX){assert(abs((b.y1+b.y2)-(box.y1+box.y2))<=2);}}}}}
